import json,torch
U=W('lm_head.weight'); g=W('model.language_model.norm.weight')
cats={
'month':"January February March April May June July August September October November December",
'weekday':"Monday Tuesday Wednesday Thursday Friday Saturday Sunday",
'color':"red blue green yellow orange purple black white brown pink gray",
'ordinal':"first second third fourth fifth sixth seventh eighth ninth tenth",
'plural':"cats dogs houses boxes children mice books cars trees apples cities wolves",
'capital':"Paris London Berlin Tokyo Rome Madrid Moscow Beijing Cairo Ottawa",
'roman':"II III IV VI VII VIII IX XI XII XIV XX",
}
def ids(s):
  out=[]
  for w in s.split():
    for v in [' '+w, w]:
      e=encode(v)
      if len(e)==1: out.append(e[0])
  return sorted(set(out))
B={}
for k,s in cats.items():
  M=U[ids(s)]; Q,_=torch.linalg.qr(M.T); B[k]=Q
for L in [28,29,30,31]:
  D=W(f'model.language_model.layers.{L}.mlp.down_proj.weight')*g[:,None]
  Dn=D/D.norm(dim=0,keepdim=True)
  fr={k:(Q.T@Dn).pow(2).sum(0) for k,Q in B.items()}
  for k in ['month','plural','roman']:
    oth=torch.stack([v for kk,v in fr.items() if kk!=k]).max(0).values
    sc=fr[k]-1.5*oth
    top=sc.argsort(descending=True)
    print(L,k,[round(float(sc[top[i]]),3) for i in (0,63,255)])
    for n in (128,256,512):
      json.dump({'kind':'mlp_cluster','layer':L,'indices':top[:n].tolist()},open(f'/work/{k}{L}_{n}.json','w'))
